/* Doom 64 Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="doom-64-light"] {
  --background: rgb(206, 206, 206);
  --foreground: rgb(31, 31, 31);
  --card: rgb(177, 177, 177);
  --card-foreground: rgb(31, 31, 31);
  --popover: rgb(177, 177, 177);
  --popover-foreground: rgb(31, 31, 31);
  --primary: rgb(183, 26, 27);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(86, 108, 48);
  --secondary-foreground: rgb(255, 255, 255);
  --muted: rgb(183, 183, 183);
  --muted-foreground: rgb(74, 74, 74);
  --accent: rgb(70, 131, 181);
  --accent-foreground: rgb(255, 255, 255);
  --destructive: rgb(255, 113, 11);
  --destructive-foreground: rgb(0, 0, 0);
  --border: rgb(80, 80, 80);
  --input: rgb(80, 80, 80);
  --ring: rgb(183, 26, 27);
  --chart-1: rgb(183, 26, 27);
  --chart-2: rgb(86, 108, 48);
  --chart-3: rgb(70, 131, 181);
  --chart-4: rgb(255, 113, 11);
  --chart-5: rgb(141, 112, 102);
  --radius: 0px;
  --sidebar: rgb(177, 177, 177);
  --sidebar-foreground: rgb(31, 31, 31);
  --sidebar-primary: rgb(183, 26, 27);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(70, 131, 181);
  --sidebar-accent-foreground: rgb(255, 255, 255);
  --sidebar-border: rgb(80, 80, 80);
  --sidebar-ring: rgb(183, 26, 27);
  --font-sans: "Oxanium", sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: "Source Code Pro", monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.4;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 4px 0px hsl(0 0% 0% / 0.2);
  --shadow-xs: 0px 2px 4px 0px hsl(0 0% 0% / 0.2);
  --shadow-sm:
    0px 2px 4px 0px hsl(0 0% 0% / 0.4), 0px 1px 2px -1px hsl(0 0% 0% / 0.4);
  --shadow:
    0px 2px 4px 0px hsl(0 0% 0% / 0.4), 0px 1px 2px -1px hsl(0 0% 0% / 0.4);
  --shadow-md:
    0px 2px 4px 0px hsl(0 0% 0% / 0.4), 0px 2px 4px -1px hsl(0 0% 0% / 0.4);
  --shadow-lg:
    0px 2px 4px 0px hsl(0 0% 0% / 0.4), 0px 4px 6px -1px hsl(0 0% 0% / 0.4);
  --shadow-xl:
    0px 2px 4px 0px hsl(0 0% 0% / 0.4), 0px 8px 10px -1px hsl(0 0% 0% / 0.4);
  --shadow-2xl: 0px 2px 4px 0px hsl(0 0% 0% / 1);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="doom-64-dark"] {
  --background: rgb(27, 27, 27);
  --foreground: rgb(225, 225, 225);
  --card: rgb(43, 43, 43);
  --card-foreground: rgb(225, 225, 225);
  --popover: rgb(43, 43, 43);
  --popover-foreground: rgb(225, 225, 225);
  --primary: rgb(230, 57, 53);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(102, 159, 52);
  --secondary-foreground: rgb(0, 0, 0);
  --muted: rgb(36, 36, 36);
  --muted-foreground: rgb(161, 161, 161);
  --accent: rgb(103, 181, 245);
  --accent-foreground: rgb(0, 0, 0);
  --destructive: rgb(253, 159, 7);
  --destructive-foreground: rgb(0, 0, 0);
  --border: rgb(74, 74, 74);
  --input: rgb(74, 74, 74);
  --ring: rgb(230, 57, 53);
  --chart-1: rgb(230, 57, 53);
  --chart-2: rgb(102, 159, 52);
  --chart-3: rgb(103, 181, 245);
  --chart-4: rgb(253, 159, 7);
  --chart-5: rgb(160, 138, 129);
  --radius: 0px;
  --sidebar: rgb(20, 20, 20);
  --sidebar-foreground: rgb(225, 225, 225);
  --sidebar-primary: rgb(230, 57, 53);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(103, 181, 245);
  --sidebar-accent-foreground: rgb(0, 0, 0);
  --sidebar-border: rgb(74, 74, 74);
  --sidebar-ring: rgb(230, 57, 53);
  --font-sans: "Oxanium", sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: "Source Code Pro", monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.6;
  --shadow-blur: 5px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 5px 0px hsl(0 0% 0% / 0.3);
  --shadow-xs: 0px 2px 5px 0px hsl(0 0% 0% / 0.3);
  --shadow-sm:
    0px 2px 5px 0px hsl(0 0% 0% / 0.6), 0px 1px 2px -1px hsl(0 0% 0% / 0.6);
  --shadow:
    0px 2px 5px 0px hsl(0 0% 0% / 0.6), 0px 1px 2px -1px hsl(0 0% 0% / 0.6);
  --shadow-md:
    0px 2px 5px 0px hsl(0 0% 0% / 0.6), 0px 2px 4px -1px hsl(0 0% 0% / 0.6);
  --shadow-lg:
    0px 2px 5px 0px hsl(0 0% 0% / 0.6), 0px 4px 6px -1px hsl(0 0% 0% / 0.6);
  --shadow-xl:
    0px 2px 5px 0px hsl(0 0% 0% / 0.6), 0px 8px 10px -1px hsl(0 0% 0% / 0.6);
  --shadow-2xl: 0px 2px 5px 0px hsl(0 0% 0% / 1.5);
}
